import argparse
import copy
import hashlib
import json
import re

ROOM_ID = "room-lantern"
SLOTS = ("2026-10-05T09:00Z", "2026-10-05T10:00Z")
INPUT_KEYS = {"requested_slot", "request_id", "confirmation"}
CONTEXT_KEYS = {"identity", "tenant", "permissions"}
OUTPUT_KEYS = {"status", "operation_id", "room_id", "slot", "evidence", "reason"}
EVIDENCE_KEYS = {"reserved", "tenant", "caller", "reconciliation_count"}
REASON_KEYS = {"code", "message"}
STATUSES = {"success", "denied", "conflict", "pending"}
TRUST_FIELDS = {"identity", "caller", "tenant", "permissions"}
REQUEST_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]{0,31}$")
IDENTITY_RE = re.compile(r"^user-[a-z0-9-]+$")
TENANT_RE = re.compile(r"^tenant-[a-z0-9-]+$")
OPERATION_RE = re.compile(r"^op-[A-Za-z0-9._-]+$")
CODE_RE = re.compile(r"^[A-Z][A-Z0-9_]{1,47}$")


def fail(message):
    raise ValueError(message)


def validate_input(payload):
    if type(payload) is not dict:
        fail("INVALID_INPUT: payload must be an object")
    if any(key in payload for key in TRUST_FIELDS):
        fail("INVALID_INPUT: exact input fields are required; injected trust fields are forbidden")
    if set(payload.keys()) != INPUT_KEYS:
        fail("INVALID_INPUT: exact input fields are required")
    slot = payload["requested_slot"]
    request_id = payload["request_id"]
    confirmation = payload["confirmation"]
    if type(slot) is not str or slot not in SLOTS:
        fail("INVALID_INPUT: unsupported requested_slot")
    if type(request_id) is not str or REQUEST_RE.fullmatch(request_id) is None:
        fail("INVALID_INPUT: invalid request_id")
    if type(confirmation) is not bool or confirmation is not True:
        fail("INVALID_INPUT: confirmation must be exactly true")
    return {"requested_slot": slot, "request_id": request_id, "confirmation": True}


def validate_context(context):
    if type(context) is not dict:
        fail("INVALID_CONTEXT: context must be an object")
    if set(context.keys()) != CONTEXT_KEYS:
        fail("INVALID_CONTEXT: exact trusted fields are required")
    identity = context["identity"]
    tenant = context["tenant"]
    permissions = context["permissions"]
    if type(identity) is not str or IDENTITY_RE.fullmatch(identity) is None:
        fail("INVALID_CONTEXT: invalid identity")
    if type(tenant) is not str or TENANT_RE.fullmatch(tenant) is None:
        fail("INVALID_CONTEXT: invalid tenant")
    if type(permissions) is not list or len(permissions) > 8:
        fail("INVALID_CONTEXT: permissions must be a list with at most eight entries")
    if any(type(item) is not str for item in permissions):
        fail("INVALID_CONTEXT: every permission must be a string")
    return {"identity": identity, "tenant": tenant, "permissions": list(permissions)}


def validate_output(result):
    if type(result) is not dict or set(result.keys()) != OUTPUT_KEYS:
        fail("POSTCONDITION_UNVERIFIED: output must contain the exact fields")
    status = result["status"]
    operation_id = result["operation_id"]
    room_id = result["room_id"]
    slot = result["slot"]
    evidence = result["evidence"]
    reason = result["reason"]
    if type(status) is not str or status not in STATUSES:
        fail("POSTCONDITION_UNVERIFIED: invalid status")
    if type(operation_id) is not str or OPERATION_RE.fullmatch(operation_id) is None:
        fail("POSTCONDITION_UNVERIFIED: invalid operation_id")
    if type(room_id) is not str or room_id != ROOM_ID:
        fail("POSTCONDITION_UNVERIFIED: invalid room_id")
    if type(slot) is not str or slot not in SLOTS:
        fail("POSTCONDITION_UNVERIFIED: invalid slot")
    if type(evidence) is not dict or set(evidence.keys()) != EVIDENCE_KEYS:
        fail("POSTCONDITION_UNVERIFIED: invalid evidence shape")
    reserved = evidence["reserved"]
    tenant = evidence["tenant"]
    caller = evidence["caller"]
    count = evidence["reconciliation_count"]
    if type(reserved) is not bool:
        fail("POSTCONDITION_UNVERIFIED: reserved must be Boolean")
    if type(tenant) is not str or TENANT_RE.fullmatch(tenant) is None:
        fail("POSTCONDITION_UNVERIFIED: invalid evidence tenant")
    if type(caller) is not str or IDENTITY_RE.fullmatch(caller) is None:
        fail("POSTCONDITION_UNVERIFIED: invalid evidence caller")
    if type(count) is not int or count < 0 or count > 1:
        fail("POSTCONDITION_UNVERIFIED: reconciliation_count must be zero or one")
    if status == "success" and reserved is not True:
        fail("POSTCONDITION_UNVERIFIED: success requires reserved evidence")
    if status != "success" and reserved is not False:
        fail("POSTCONDITION_UNVERIFIED: non-success cannot claim a reservation")
    if type(reason) is not dict or set(reason.keys()) != REASON_KEYS:
        fail("POSTCONDITION_UNVERIFIED: invalid reason shape")
    code = reason["code"]
    message = reason["message"]
    if type(code) is not str or CODE_RE.fullmatch(code) is None:
        fail("POSTCONDITION_UNVERIFIED: invalid reason code")
    if type(message) is not str or not 1 <= len(message) <= 160:
        fail("POSTCONDITION_UNVERIFIED: invalid reason message")
    return copy.deepcopy(result)


def canonical_digest(context, payload):
    material = {
        "tenant": context["tenant"],
        "caller": context["identity"],
        "request_id": payload["request_id"],
        "payload": payload
    }
    encoded = json.dumps(material, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(encoded.encode("utf-8")).hexdigest()


def safe_slot(payload):
    if type(payload) is dict:
        value = payload.get("requested_slot")
        if type(value) is str and value in SLOTS:
            return value
    return SLOTS[0]


def safe_principal(context):
    try:
        clean = validate_context(context)
        return clean["tenant"], clean["identity"]
    except ValueError:
        return "tenant-unknown", "user-unknown"


def diagnostic(status, operation_id, slot, context, code, message, count=0):
    tenant, caller = safe_principal(context)
    candidate = {
        "status": status,
        "operation_id": operation_id,
        "room_id": ROOM_ID,
        "slot": slot if type(slot) is str and slot in SLOTS else SLOTS[0],
        "evidence": {
            "reserved": False,
            "tenant": tenant,
            "caller": caller,
            "reconciliation_count": count
        },
        "reason": {"code": code, "message": message}
    }
    return validate_output(candidate)


class RoomService:
    def __init__(self, rooms=None, test_output_transform=None):
        self.rooms = copy.deepcopy(rooms) if rooms is not None else {}
        self.cache = {}
        self.sequence = 0
        self._test_output_transform = test_output_transform

    def reserve(self, payload, context, evidence_mode="confirmed"):
        try:
            clean = validate_input(payload)
            trusted = validate_context(context)
        except ValueError as exc:
            return diagnostic("denied", "op-rejected", safe_slot(payload), context,
                              "BOUNDARY_REJECTED", str(exc))
        if type(evidence_mode) is not str or evidence_mode not in {"confirmed", "uncertain"}:
            return diagnostic("denied", "op-rejected", clean["requested_slot"], trusted,
                              "INVALID_MODE", "evidence_mode must be confirmed or uncertain")
        if "reserve:study-room" not in trusted["permissions"]:
            return diagnostic("denied", "op-denied", clean["requested_slot"], trusted,
                              "PERMISSION_DENIED", "reserve:study-room permission is required")

        digest = canonical_digest(trusted, clean)
        key = (trusted["tenant"], trusted["identity"], clean["request_id"])
        old = self.cache.get(key)
        if old is not None:
            if old["digest"] != digest:
                return diagnostic("conflict", old["operation_id"], clean["requested_slot"], trusted,
                                  "IDEMPOTENCY_CONFLICT", "request_id was already used with a different payload")
            try:
                return validate_output(copy.deepcopy(old["result"]))
            except ValueError as exc:
                return diagnostic("denied", "op-rejected", clean["requested_slot"], trusted,
                                  "POSTCONDITION_UNVERIFIED", str(exc))

        slot = clean["requested_slot"]
        owner = self.rooms.get((ROOM_ID, slot))
        if owner is not None:
            return diagnostic("conflict", "op-conflict", slot, trusted,
                              "SLOT_CONFLICT", "the requested slot is already reserved")

        rooms_before = copy.deepcopy(self.rooms)
        cache_before = copy.deepcopy(self.cache)
        sequence_before = self.sequence
        self.sequence += 1
        operation_id = "op-{:04d}".format(self.sequence)
        self.rooms[(ROOM_ID, slot)] = (trusted["tenant"], trusted["identity"])
        pending = evidence_mode == "uncertain"
        candidate = {
            "status": "pending" if pending else "success",
            "operation_id": operation_id,
            "room_id": ROOM_ID,
            "slot": slot,
            "evidence": {
                "reserved": not pending,
                "tenant": trusted["tenant"],
                "caller": trusted["identity"],
                "reconciliation_count": 0
            },
            "reason": {
                "code": "UNCERTAIN_EFFECT" if pending else "RESERVATION_CONFIRMED",
                "message": "effect evidence is not yet confirmed" if pending else "reservation postcondition is confirmed"
            }
        }
        try:
            rendered = copy.deepcopy(candidate)
            if self._test_output_transform is not None:
                rendered = self._test_output_transform(rendered)
            rendered = validate_output(rendered)
            self.cache[key] = {
                "digest": digest,
                "operation_id": operation_id,
                "payload": copy.deepcopy(clean),
                "result": copy.deepcopy(rendered),
                "reconciliation_count": 0
            }
            return copy.deepcopy(rendered)
        except Exception as exc:
            self.rooms = rooms_before
            self.cache = cache_before
            self.sequence = sequence_before
            return diagnostic("denied", "op-rejected", slot, trusted,
                              "POSTCONDITION_UNVERIFIED", "output validation failed: " + str(exc))

    def reconcile(self, payload, context):
        try:
            clean = validate_input(payload)
            trusted = validate_context(context)
        except ValueError as exc:
            return diagnostic("denied", "op-rejected", safe_slot(payload), context,
                              "BOUNDARY_REJECTED", str(exc))
        if "reserve:study-room" not in trusted["permissions"]:
            return diagnostic("denied", "op-denied", clean["requested_slot"], trusted,
                              "PERMISSION_DENIED", "reserve:study-room permission is required")

        digest = canonical_digest(trusted, clean)
        key = (trusted["tenant"], trusted["identity"], clean["request_id"])
        entry = self.cache.get(key)
        if entry is None:
            return diagnostic("conflict", "op-missing", clean["requested_slot"], trusted,
                              "OPERATION_NOT_FOUND", "no matching operation exists")
        if entry["digest"] != digest or entry["payload"] != clean:
            return diagnostic("conflict", entry["operation_id"], clean["requested_slot"], trusted,
                              "IDEMPOTENCY_CONFLICT", "payload does not match the stored operation")

        try:
            current = validate_output(copy.deepcopy(entry["result"]))
        except ValueError as exc:
            return diagnostic("denied", "op-rejected", clean["requested_slot"], trusted,
                              "POSTCONDITION_UNVERIFIED", str(exc))
        if current["status"] != "pending":
            return current
        if entry["reconciliation_count"] >= 1:
            current["reason"] = {
                "code": "RECONCILIATION_LIMIT",
                "message": "bounded reconciliation was already attempted"
            }
            entry["result"] = copy.deepcopy(validate_output(current))
            return copy.deepcopy(entry["result"])

        entry["reconciliation_count"] = 1
        current["evidence"]["reconciliation_count"] = 1
        expected_owner = (trusted["tenant"], trusted["identity"])
        if self.rooms.get((ROOM_ID, clean["requested_slot"])) == expected_owner:
            current["status"] = "success"
            current["evidence"]["reserved"] = True
            current["reason"] = {
                "code": "RECONCILED_CONFIRMED",
                "message": "one bounded state check confirmed the reservation"
            }
        else:
            current["reason"] = {
                "code": "RECONCILIATION_UNCONFIRMED",
                "message": "one bounded state check could not confirm the reservation"
            }
        entry["result"] = copy.deepcopy(validate_output(current))
        return copy.deepcopy(entry["result"])


def run_demo(fixture):
    service = RoomService()
    first = service.reserve(fixture["payload"], fixture["context"])
    replay = service.reserve(fixture["payload"], fixture["context"])
    state = {"{}|{}".format(key[0], key[1]): value for key, value in service.rooms.items()}
    return {"first": first, "replay": replay, "state": state}


def load_fixture(path):
    with open(path, encoding="utf-8") as handle:
        value = json.load(handle)
    if type(value) is not dict or set(value.keys()) != {"context", "payload"}:
        fail("fixture must contain exact context and payload fields")
    return value


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--demo", required=True, choices=["worked", "changed"])
    args = parser.parse_args()
    filename = "worked_fixture.json" if args.demo == "worked" else "changed_fixture.json"
    print(json.dumps(run_demo(load_fixture(filename)), sort_keys=True))

