ALLOWED_KEYS = {"tenant", "requested_slot", "request_id", "confirmation"}
ALLOWED_SLOTS = {"2026-10-05T09:00Z", "2026-10-05T10:00Z"}


class InsecureSchemaOnlyService:
    def __init__(self):
        self.rooms = {}

    def reserve(self, payload):
        if type(payload) is not dict or set(payload.keys()) != ALLOWED_KEYS:
            raise ValueError("wrong variant requires its permissive schema")
        if type(payload["tenant"]) is not str or not payload["tenant"].startswith("tenant-"):
            raise ValueError("wrong variant rejected tenant shape")
        if type(payload["requested_slot"]) is not str or payload["requested_slot"] not in ALLOWED_SLOTS:
            raise ValueError("wrong variant rejected slot")
        if type(payload["request_id"]) is not str:
            raise ValueError("wrong variant rejected request_id")
        if type(payload["confirmation"]) is not bool or payload["confirmation"] is not True:
            raise ValueError("wrong variant rejected confirmation")
        key = (ROOM_ID, payload["requested_slot"])
        self.rooms[key] = payload["tenant"]
        return {"status": "mutated", "tenant_used": payload["tenant"]}
